1	package com.loja.checkout.service;
2	
3	import com.loja.checkout.clube.NivelClube;
4	import com.loja.checkout.cupom.Cupom;
5	import com.loja.checkout.cupom.CupomContexto;
6	import com.loja.checkout.dto.ItemRequest;
7	import com.loja.checkout.dto.ResumoRequest;
8	import com.loja.checkout.dto.ResumoResponse;
9	import com.loja.checkout.entrega.ModalidadeEntrega;
10	import com.loja.checkout.erro.CodigoErro;
11	import com.loja.checkout.erro.PedidoException;
12	import com.loja.checkout.pagamento.AjustePagamento;
13	import com.loja.checkout.pagamento.FormaPagamento;
14	import com.loja.checkout.regiao.Regiao;
15	import com.loja.checkout.util.Dinheiro;
16	import org.springframework.stereotype.Service;
17	
18	import java.math.BigDecimal;
19	import java.util.List;
20	
21	@Service
22	public class CalculadoraResumoService {
23	
24	    public ResumoResponse calcular(ResumoRequest request) {
25	        validarItens(request.itens());
26	        NivelClube nivelClube = NivelClube.fromCodigo(request.nivelClube())
27	                .orElseThrow(() -> new PedidoException(CodigoErro.NIVEL_CLUBE_INVALIDO));
28	        Regiao regiao = Regiao.fromCodigo(request.regiao())
29	                .orElseThrow(() -> new PedidoException(CodigoErro.REGIAO_INVALIDA));
30	        ModalidadeEntrega modalidade = ModalidadeEntrega.fromCodigo(request.modalidadeEntrega())
31	                .orElseThrow(() -> new PedidoException(CodigoErro.MODALIDADE_INVALIDA));
32	
33	        BigDecimal subtotal = calcularSubtotal(request.itens());
34	        BigDecimal pesoTotal = calcularPesoTotal(request.itens());
35	
36	        if (!modalidade.disponivel(pesoTotal)) {
37	            throw new PedidoException(CodigoErro.MODALIDADE_INDISPONIVEL);
38	        }
39	
40	        BigDecimal frete = nivelClube.isentaFrete()
41	                ? new BigDecimal("0.00")
42	                : modalidade.calcularFrete(pesoTotal);
43	
44	        BigDecimal descontoCupom = calcularDescontoCupom(request.cupom(), subtotal, frete, request.itens());
45	
46	        FormaPagamento formaPagamento = FormaPagamento.fromCodigo(request.formaPagamento())
47	                .orElseThrow(() -> new PedidoException(CodigoErro.FORMA_PAGAMENTO_INVALIDA));
48	
49	        int parcelas = request.parcelas() == null ? 1 : request.parcelas();
50	        if (!formaPagamento.parcelaValida(parcelas)) {
51	            throw new PedidoException(CodigoErro.PARCELAMENTO_INVALIDO);
52	        }
53	
54	        BigDecimal seguro = Dinheiro.arredondar(subtotal.multiply(regiao.percentualSeguro()));
55	        BigDecimal totalPedido = subtotal.subtract(descontoCupom).add(frete).add(seguro);
56	
57	        if (!formaPagamento.disponivel(totalPedido)) {
58	            throw new PedidoException(CodigoErro.FORMA_PAGAMENTO_INDISPONIVEL);
59	        }
60	
61	        AjustePagamento ajustePagamento = formaPagamento.calcular(totalPedido, parcelas);
62	
63	        BigDecimal credito = nivelClube.calcularCredito(subtotal);
64	        boolean brinde = nivelClube.temBrinde(subtotal);
65	
66	        return new ResumoResponse(
67	                subtotal,
68	                descontoCupom,
69	                frete,
70	                modalidade.prazoDias(),
71	                seguro,
72	                ajustePagamento.ajuste(),
73	                ajustePagamento.totalFinal(),
74	                parcelas,
75	                ajustePagamento.valorParcela(),
76	                credito,
77	                brinde);
78	    }
79	
80	    private void validarItens(List<ItemRequest> itens) {
81	        if (itens == null || itens.isEmpty()) {
82	            throw new PedidoException(CodigoErro.PEDIDO_INVALIDO);
83	        }
84	        for (ItemRequest item : itens) {
85	            boolean precoInvalido = item.precoUnitario() == null || item.precoUnitario().signum() <= 0;
86	            boolean quantidadeInvalida = item.quantidade() == null || item.quantidade() <= 0;
87	            boolean pesoInvalido = item.pesoKg() == null || item.pesoKg().signum() <= 0;
88	            if (precoInvalido || quantidadeInvalida || pesoInvalido) {
89	                throw new PedidoException(CodigoErro.PEDIDO_INVALIDO);
90	            }
91	        }
92	    }
93	
94	    private BigDecimal calcularSubtotal(List<ItemRequest> itens) {
95	        BigDecimal subtotal = BigDecimal.ZERO;
96	        for (ItemRequest item : itens) {
97	            subtotal = subtotal.add(item.precoUnitario().multiply(BigDecimal.valueOf(item.quantidade())));
98	        }
99	        return Dinheiro.arredondar(subtotal);
100	    }
101	
102	    private BigDecimal calcularPesoTotal(List<ItemRequest> itens) {
103	        BigDecimal peso = BigDecimal.ZERO;
104	        for (ItemRequest item : itens) {
105	            peso = peso.add(item.pesoKg().multiply(BigDecimal.valueOf(item.quantidade())));
106	        }
107	        return peso;
108	    }
109	
110	    private BigDecimal calcularDescontoCupom(String codigoCupom, BigDecimal subtotal, BigDecimal frete,
111	            List<ItemRequest> itens) {
112	        if (codigoCupom == null || codigoCupom.isBlank()) {
113	            return new BigDecimal("0.00");
114	        }
115	        Cupom cupom = Cupom.fromCodigo(codigoCupom)
116	                .orElseThrow(() -> new PedidoException(CodigoErro.CUPOM_INVALIDO));
117	        CupomContexto contexto = new CupomContexto(subtotal, frete, itens);
118	        if (!cupom.aplicavel(contexto)) {
119	            throw new PedidoException(CodigoErro.CUPOM_NAO_APLICAVEL);
120	        }
121	        return cupom.calcularDesconto(contexto);
122	    }
123	}
