3	import com.loja.checkout.util.Dinheiro;
4	
5	import java.math.BigDecimal;
6	import java.math.MathContext;
7	import java.math.RoundingMode;
8	import java.util.Optional;
9	
10	public enum FormaPagamento {
11	
12	    PIX {
13	        @Override
14	        public boolean parcelaValida(int parcelas) {
15	            return parcelas == 1;
16	        }
17	
18	        @Override
19	        public boolean disponivel(BigDecimal totalPedido) {
20	            return true;
21	        }
22	
23	        @Override
24	        public AjustePagamento calcular(BigDecimal totalPedido, int parcelas) {
25	            BigDecimal desconto = Dinheiro.arredondar(totalPedido.multiply(new BigDecimal("0.05")));
26	            BigDecimal totalFinal = totalPedido.subtract(desconto);
27	            return new AjustePagamento(totalFinal, totalFinal, desconto.negate());
28	        }
29	    },
30	
31	    BOLETO {
32	        @Override
33	        public boolean parcelaValida(int parcelas) {
34	            return parcelas == 1;
35	        }
36	
37	        @Override
38	        public boolean disponivel(BigDecimal totalPedido) {
39	            return totalPedido.compareTo(new BigDecimal("1000.00")) <= 0;
40	        }
41	
42	        @Override
43	        public AjustePagamento calcular(BigDecimal totalPedido, int parcelas) {
44	            BigDecimal tarifa = new BigDecimal("3.49");
45	            BigDecimal totalFinal = totalPedido.add(tarifa);
46	            return new AjustePagamento(totalFinal, totalFinal, tarifa);
47	        }
48	    },
49	
50	    CARTAO {
51	        @Override
52	        public boolean parcelaValida(int parcelas) {
53	            return parcelas >= 1 && parcelas <= 12;
54	        }
55	
56	        @Override
57	        public boolean disponivel(BigDecimal totalPedido) {
58	            return true;
59	        }
60	
61	        @Override
62	        public AjustePagamento calcular(BigDecimal totalPedido, int parcelas) {
63	            if (parcelas <= 3) {
64	                BigDecimal valorParcela = Dinheiro.arredondar(
65	                        totalPedido.divide(BigDecimal.valueOf(parcelas), MathContext.DECIMAL128));
66	                return new AjustePagamento(totalPedido, valorParcela, new BigDecimal("0.00"));
67	            }
68	
69	            BigDecimal taxa = new BigDecimal("0.0199");
70	            BigDecimal fator = BigDecimal.ONE.add(taxa).pow(parcelas, MathContext.DECIMAL128);
71	            BigDecimal valorParcela = Dinheiro.arredondar(
72	                    totalPedido.multiply(taxa).multiply(fator)
73	                            .divide(fator.subtract(BigDecimal.ONE), MathContext.DECIMAL128));
74	            BigDecimal totalFinal = valorParcela.multiply(BigDecimal.valueOf(parcelas))
75	                    .setScale(2, RoundingMode.HALF_EVEN);
76	            BigDecimal ajuste = totalFinal.subtract(totalPedido);
77	            return new AjustePagamento(totalFinal, valorParcela, ajuste);
78	        }
79	    };
80	
81	    public abstract boolean parcelaValida(int parcelas);
82	
83	    public abstract boolean disponivel(BigDecimal totalPedido);
84	
85	    public abstract AjustePagamento calcular(BigDecimal totalPedido, int parcelas);
